"""
Generates the extended Kinetic icon set as literal SVG path strings.

Run:  python3 scripts/icons/gen.py  →  writes packages/icons/src/extra.ts
Every icon is drawn on a 24×24 grid for a 2px round stroke, matching the
original 70. Helpers keep the geometry readable; the output is plain strings.
"""
import math, json, os

def f(n):
    n = round(n, 2)
    return str(int(n)) if n == int(n) else str(n)

def C(cx, cy, r):
    return f"M{f(cx-r)} {f(cy)}a{f(r)} {f(r)} 0 1 0 {f(2*r)} 0a{f(r)} {f(r)} 0 1 0 {f(-2*r)} 0"

def R(x, y, w, h, r=0):
    if not r:
        return f"M{f(x)} {f(y)}h{f(w)}v{f(h)}h{f(-w)}z"
    return (f"M{f(x+r)} {f(y)}h{f(w-2*r)}a{f(r)} {f(r)} 0 0 1 {f(r)} {f(r)}v{f(h-2*r)}"
            f"a{f(r)} {f(r)} 0 0 1 {f(-r)} {f(r)}h{f(-(w-2*r))}a{f(r)} {f(r)} 0 0 1 {f(-r)} {f(-r)}"
            f"v{f(-(h-2*r))}a{f(r)} {f(r)} 0 0 1 {f(r)} {f(-r)}z")

def P(*pts, close=False):
    s = "M" + " L".join(f"{f(x)} {f(y)}" for x, y in pts)
    return s + ("z" if close else "")

def L(x1, y1, x2, y2):
    return f"M{f(x1)} {f(y1)}L{f(x2)} {f(y2)}"

def ARC(cx, cy, r, a0, a1):
    """Arc from angle a0 to a1 (degrees, 0 = east, clockwise positive in screen space)."""
    x0, y0 = cx + r * math.cos(math.radians(a0)), cy + r * math.sin(math.radians(a0))
    x1, y1 = cx + r * math.cos(math.radians(a1)), cy + r * math.sin(math.radians(a1))
    large = 1 if (a1 - a0) % 360 > 180 else 0
    return f"M{f(x0)} {f(y0)}A{f(r)} {f(r)} 0 {large} 1 {f(x1)} {f(y1)}"

def DOT(x, y):
    return f"M{f(x)} {f(y)}h.01"

def J(*parts):
    return "".join(parts)

