out_path = os.path.join(os.path.dirname(__file__), "..", "..", "packages", "icons", "src", "extra.ts")
lines = [
    "// Generated by scripts/icons/gen.py — do not edit by hand.",
    "/** Extended Kinetic icon set: 24×24 grid, 2px round stroke. */",
    "export const extraIconPaths = {",
]
for k, v in icons.items():
    lines.append(f"  {json.dumps(k)}: {json.dumps(v)},")
lines.append("} as const;")
open(out_path, "w").write("\n".join(lines) + "\n")
comp_path = os.path.join(os.path.dirname(out_path), "extra-icons.ts")
pascal = lambda k: "".join(p.capitalize() for p in k.split("-")) + "Icon"
comp = ["// Generated by scripts/icons/gen.py — do not edit by hand.", 'import { createIcon } from "./create-icon";', 'import { extraIconPaths as p } from "./extra";', ""]
for k in icons:
    comp.append(f'export const {pascal(k)} = createIcon("{pascal(k)}", p[{json.dumps(k)}]);')
open(comp_path, "w").write("\n".join(comp) + "\n")
print(f"{len(icons)} icons → {os.path.relpath(out_path)} + extra-icons.ts")
